pub fn intersperse(numbers: &[i32], delim: i32) -> Vec<i32> {
    if numbers.is_empty() {
        return Vec::new();
    }

    let n = numbers.len();
    // We will have 2n - 1 elements after interspersing
    let mut res = Vec::with_capacity(2 * n - 1);

    for (i, &num) in numbers.iter().enumerate() {
        if i > 0 {
            res.push(delim);
        }
        res.push(num);
    }

    res
}

